#include <string.h>
#include <stdio.h>
int copy_text(char *dst, size_t cap, const char *src) { size_t n=strlen(src); if(dst==NULL || src==NULL || cap==0 || n>=cap) return 0; memcpy(dst,src,n+1); return 1; }
int main(void) { char out[16]; if(!copy_text(out,sizeof out,"C language")) return 1; puts(out); return 0; }
